{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may terminate a tenancy only for a listed just cause, such as nonpayment, nuisance, illegal use, or an owner or family move-in, and must provide relocation assistance for no-fault evictions.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles that are not regulated by the City’s Rent Stabilization Ordinance; the tenant must have lived in the unit at least six months or the original lease must have expired.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"No building-age cutoff; can apply to buildings newer than October 1, 1978 and to single-family dwellings"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner’s roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term treatment centers for substance abuse, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"JCO covers units not regulated by the City’s RSO and does not regulate rent increases; state law AB 1482 may regulate rent.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Fair Market Rent threshold for nonpayment-of-rent evictions","requirement":"A landlord may not evict a tenant who falls behind in rent unless the amount owed is higher than the Fair Market Rent for the unit’s bedroom size.","key_value":"rent owed must exceed the Fair Market Rent (set by bedroom size)","coverage_conditions":"All City of Los Angeles RSO and JCO rental units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Applies to all RSO & JCO rental units in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Just Cause For Eviction Ordinance (JCO) – LAHD, Evictions for Non-Payment of Rent","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR). The FMR depends on the bedroom size of the rental unit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"A landlord of a covered unit may not raise rent by more than 5% plus the regional cost-of-living change, or 10%, whichever is lower, in a 12-month period.","key_value":"5% + CPI, max 10%; 8.9% for Aug 1, 2024 – Jul 31, 2025","coverage_conditions":"Units more than 15 years old, determined on a rolling basis, that are not already subject to the City’s Rent Stabilization Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"15-year rolling age cutoff measured from construction date"},"exemptions":"Units constructed within the last 15 years; deed-restricted affordable units; certain dormitories; a two-unit property where the owner occupied the second unit for the entire tenancy; single-family homes and condominiums owned by a natural person who gave the required written notice; units under the City’s RSO.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%. Previously, from August 1, 2023 to July 31, 2024 the maximum annual increase for units subject to AB 1482 was 8.8%.","interaction":"Single-family homes and condominiums exempt from state law may still be covered by the City’s JCO.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
